Q["a2-cases-accusative-plural"] = {"version":1,"id":"a2-cases-accusative-plural","topic":"a2-cases-accusative-plural","level":"A2","title":"Stop: accusative plural","passScore":3,"items":[{"id":"a2-cases-accusative-plural-q1","type":"multiple-choice","kind":"form","prompt":"Lubię ___. (I like cats.)","options":["kotów","koty","kotami","kota"],"correct":1,"explanation":"Animals in the plural: the accusative is the same as the nominative, koty.","optionNotes":["-ów is for men (studentów), not for animals.",null,"Kotami is the instrumental.","Kota is singular: \"a cat\"."]},{"id":"a2-cases-accusative-plural-q2","type":"multiple-choice","kind":"form","prompt":"Znam ___. (these students)","options":["te studenty","ci studenci","tych studenci","tych studentów"],"correct":3,"explanation":"Men as objects take -ów, and \"these\" is tych.","optionNotes":["Studenty does not exist; for men use the masculine personal forms.","This is the nominative: the subject form.","The noun must change too: studentów.",null]},{"id":"a2-cases-accusative-plural-q3","type":"multiple-choice","kind":"form","prompt":"W weekend odwiedzam ___.","options":["rodziców","rodzice","rodzicami","rodzicy"],"correct":0,"explanation":"Rodzice is masculine personal, so the accusative is rodziców.","optionNotes":[null,"Rodzice is the nominative; the object form is rodziców.","Rodzicami is the instrumental.","Not a word: the ending is -ów."]},{"id":"a2-cases-accusative-plural-q4","type":"multiple-choice","kind":"form","prompt":"Czytam ___. (Polish books)","options":["polskich książek","polskie książki","polskich książki","polskie książek"],"correct":1,"explanation":"Books are things: the accusative plural is the same as the nominative, polskie książki.","optionNotes":["This is the genitive plural (dużo polskich książek).",null,"The adjective -ich is only for men here.","Książek is the genitive plural."]}]};
Q["a2-cases-dative"] = {"version":1,"id":"a2-cases-dative","topic":"a2-cases-dative","level":"A2","title":"Stop: dative","passScore":3,"items":[{"id":"a2-cases-dative-q1","type":"multiple-choice","kind":"form","prompt":"Daję ___ prezent. (I'm giving Mum a present.)","options":["mamę","mamie","do mamy","mama"],"correct":1,"explanation":"The person who gets something takes the dative. Feminine -a → -e with softening: mamie.","optionNotes":["Accusative: that is for the present, the object.",null,"Do means \"to a place\"; for a person who receives something use the dative.","Nominative, the dictionary form."]},{"id":"a2-cases-dative-q2","type":"multiple-choice","kind":"form","prompt":"Często pomagamy ___. (our neighbour, a man)","options":["naszego sąsiada","naszemu sąsiadowi","nasz sąsiad","naszym sąsiadem"],"correct":1,"explanation":"Pomagać takes the dative: adjective -emu, masculine noun -owi.","optionNotes":["Accusative, as after \"help\" in English; pomagać takes the dative.",null,"Nominative.","Instrumental."]},{"id":"a2-cases-dative-q3","type":"multiple-choice","kind":"form","prompt":"I like this dress.","options":["Podobam się tę sukienkę.","Ta sukienka podoba mnie.","Podoba mi się ta sukienka.","Jestem podoba ta sukienka."],"correct":2,"explanation":"With podobać się the thing is the subject and the person is in the dative: Podoba mi się ta sukienka.","optionNotes":["Podobam się means \"I appeal (to someone)\"; the dress must be the subject.","Podobać needs się, and the usual dative here is the short mi.",null,"Być is not used here."]},{"id":"a2-cases-dative-q4","type":"multiple-choice","kind":"form","prompt":"I'm cold.","options":["Jestem zimno.","Mam zimno.","Jestem zimny.","Jest mi zimno."],"correct":3,"explanation":"Feeling cold or hot: jest + dative + adverb, \"it is cold to me\".","optionNotes":["A word-for-word copy of \"I am cold\".","Not standard Polish; say jest mi zimno.","Jestem zimny describes a cold person or a cold body, not how you feel.",null]}]};
Q["a2-cases-genitive-plural-quantities"] = {"version":1,"id":"a2-cases-genitive-plural-quantities","topic":"a2-cases-genitive-plural-quantities","level":"A2","title":"Stop: genitive plural","passScore":3,"items":[{"id":"a2-cases-genitive-plural-quantities-q1","type":"multiple-choice","kind":"form","prompt":"W centrum jest dużo ___. (restaurants)","options":["restauracje","restauracjów","restauracji","restauracja"],"correct":2,"explanation":"After dużo the genitive plural; nouns in -ja take -i: restauracji.","optionNotes":["Restauracje is the nominative plural.","Feminine nouns don't take -ów.",null,"Restauracja is singular."]},{"id":"a2-cases-genitive-plural-quantities-q2","type":"multiple-choice","kind":"form","prompt":"Poczekam kilka ___.","options":["minut","minuty","minutów","minuta"],"correct":0,"explanation":"After kilka the genitive plural; feminine nouns lose the -a: minut.","optionNotes":[null,"Minuty is the form after 2, 3, 4.","Feminine nouns don't take -ów.","Minuta is singular."]},{"id":"a2-cases-genitive-plural-quantities-q3","type":"multiple-choice","kind":"form","prompt":"Przepraszamy, nie ma już ___.","options":["bilety","biletów","biletami","bilet"],"correct":1,"explanation":"Nie ma takes the genitive; in the plural: biletów.","optionNotes":["Bilety is the nominative.",null,"Biletami is the instrumental.","Bilet is the nominative singular."]},{"id":"a2-cases-genitive-plural-quantities-q4","type":"multiple-choice","kind":"form","prompt":"Ile masz ___? (books)","options":["książki","książkach","książków","książek"],"correct":3,"explanation":"After ile the genitive plural; książka → książek (an e is added).","optionNotes":["Książki is the nominative.","Książkach is the locative.","Feminine nouns don't take -ów.",null]}]};
Q["a2-cases-instrumental-full"] = {"version":1,"id":"a2-cases-instrumental-full","topic":"a2-cases-instrumental-full","level":"A2","title":"Stop: instrumental","passScore":3,"items":[{"id":"a2-cases-instrumental-full-q1","type":"multiple-choice","kind":"form","prompt":"Jadę do pracy ___. (by bus)","options":["z autobusem","autobusem","na autobusie","w autobusie"],"correct":1,"explanation":"How you travel: the vehicle in the instrumental, with no preposition.","optionNotes":["Z autobusem means \"together with a bus\".",null,"Na + locative says where something is, not how you travel.","W autobusie means \"inside the bus\" (where you are)."]},{"id":"a2-cases-instrumental-full-q2","type":"multiple-choice","kind":"form","prompt":"Idę do kina z ___. (my friends)","options":["moi przyjaciele","moich przyjaciół","moim przyjaciołom","moimi przyjaciółmi"],"correct":3,"explanation":"Z meaning \"with\" takes the instrumental: moimi przyjaciółmi (irregular -mi).","optionNotes":["Nominative.","Genitive: z + genitive means \"from\".","Dative.",null]},{"id":"a2-cases-instrumental-full-q3","type":"multiple-choice","kind":"form","prompt":"Ola interesuje się ___. (art)","options":["sztuką","sztuka","sztukę","o sztuce"],"correct":0,"explanation":"Interesować się takes the instrumental: sztuka → sztuką.","optionNotes":[null,"Nominative.","Accusative.","A copy of \"interested in / about\"; no preposition here."]},{"id":"a2-cases-instrumental-full-q4","type":"multiple-choice","kind":"form","prompt":"Kot śpi pod ___. (the table)","options":["stół","stole","stołem","stołu"],"correct":2,"explanation":"Pod meaning \"under\" (where) takes the instrumental: stołem.","optionNotes":["Nominative (also the accusative, used for \"where to\").","Locative, as in na stole.",null,"Genitive."]}]};
Q["a2-cases-locative-full"] = {"version":1,"id":"a2-cases-locative-full","topic":"a2-cases-locative-full","level":"A2","title":"Stop: locative","passScore":3,"items":[{"id":"a2-cases-locative-full-q1","type":"multiple-choice","kind":"form","prompt":"Rozmawiamy o ___. (the weather)","options":["pogoda","pogodę","pogodzie","pogodą"],"correct":2,"explanation":"\"About\" after rozmawiać takes the locative: pogoda → pogodzie (d → dzi).","optionNotes":["Nominative.","Accusative: o + accusative is for asking for something (pytać o drogę).",null,"Instrumental."]},{"id":"a2-cases-locative-full-q2","type":"multiple-choice","kind":"form","prompt":"Po ___ jadę do domu. (the lesson)","options":["lekcja","lekcji","lekcję","lekcją"],"correct":1,"explanation":"Po meaning \"after\" takes the locative: lekcja → lekcji.","optionNotes":["Nominative.",null,"Accusative.","Instrumental."]},{"id":"a2-cases-locative-full-q3","type":"multiple-choice","kind":"form","prompt":"___ jadę do Rzymu. (Next year)","options":["W przyszły rok","Na przyszłym roku","W przyszłego roku","W przyszłym roku"],"correct":3,"explanation":"\"Next / this / last year\" is w + locative: w przyszłym roku.","optionNotes":["The noun and adjective must take the locative.","Time phrases use w, not na.","Genitive endings.",null]},{"id":"a2-cases-locative-full-q4","type":"multiple-choice","kind":"form","prompt":"W ___ jest dużo ludzi. (shops)","options":["sklepach","sklepami","sklepy","sklepów"],"correct":0,"explanation":"The locative plural is -ach for every gender: w sklepach.","optionNotes":[null,"-ami is the instrumental plural.","Nominative plural.","Genitive plural."]}]};
Q["a2-cases-nominative-plural"] = {"version":1,"id":"a2-cases-nominative-plural","topic":"a2-cases-nominative-plural","level":"A2","title":"Stop: nominative plural","passScore":3,"items":[{"id":"a2-cases-nominative-plural-q1","type":"multiple-choice","kind":"form","prompt":"Moi ___ są bardzo mili. (colleagues)","options":["kolegi","koledzy","kolegowie","kolegy"],"correct":1,"explanation":"Kolega is a man: masculine personal -y, and g → dz: koledzy.","optionNotes":["After g the masculine personal ending is -y with g → dz.",null,"-owie is for a few nouns like panowie, synowie.","The g must change to dz: koledzy."]},{"id":"a2-cases-nominative-plural-q2","type":"multiple-choice","kind":"form","prompt":"Te ___ są nowe. (books)","options":["książky","książke","książki","książkie"],"correct":2,"explanation":"After k Polish writes -i, never -y: książki.","optionNotes":["After k you cannot write y.","-e is the plural after soft consonants (klucze), not after k.",null,"Not a word: the ending is just -i."]},{"id":"a2-cases-nominative-plural-q3","type":"multiple-choice","kind":"form","prompt":"Which phrase is correct? (good doctors)","options":["dobre lekarze","dobrzy lekarzy","dobry lekarze","dobrzy lekarze"],"correct":3,"explanation":"Doctors here are men: masculine personal dobrzy (r → rz) + lekarze.","optionNotes":["Dobre is for women, animals and things.","Lekarzy is the genitive plural (dużo lekarzy).","Dobry is singular.",null]},{"id":"a2-cases-nominative-plural-q4","type":"multiple-choice","kind":"form","prompt":"Ania i Tomek są ___. (tired)","options":["zmęczeni","zmęczone","zmęczony","zmęczona"],"correct":0,"explanation":"A group with a man takes the masculine personal form: zmęczeni.","optionNotes":[null,"Zmęczone is for groups without men.","Zmęczony is singular, for one man.","Zmęczona is singular, for one woman."]}]};
Q["a2-functions-describing"] = {"version":1,"id":"a2-functions-describing","topic":"a2-functions-describing","level":"A2","title":"Stop: describing","passScore":3,"items":[{"id":"a2-functions-describing-q1","type":"multiple-choice","kind":"function","prompt":"What's your new neighbour like?","options":["Jak jest twój nowy sąsiad?","Jaki jest twój nowy sąsiad?","Jaka jest twój nowy sąsiad?","Co jest twój nowy sąsiad?"],"correct":1,"explanation":"\"What … like?\" is Jaki …?, agreeing with the noun: jaki sąsiad.","optionNotes":["Jak asks \"how\"; a word-for-word copy of \"how is…\".",null,"Jaka is feminine; sąsiad is masculine.","Co asks \"what\" about things."]},{"id":"a2-functions-describing-q2","type":"multiple-choice","kind":"function","prompt":"The flat is very bright.","options":["Mieszkanie jest bardzo jasno.","Mieszkanie jest bardzo jasny.","Mieszkanie jest bardzo jasne.","Mieszkanie ma bardzo jasne."],"correct":2,"explanation":"A noun is described with an adjective, and it agrees: mieszkanie jasne.","optionNotes":["Jasno is an adverb; a noun needs an adjective.","Jasny is masculine; mieszkanie is neuter.",null,"Mieć needs an object; use jest + adjective."]},{"id":"a2-functions-describing-q3","type":"multiple-choice","kind":"function","prompt":"This jacket is too expensive.","options":["Ta kurtka jest za droga.","Ta kurtka jest za dużo droga.","Ta kurtka jest też droga.","Ta kurtka jest za drogo."],"correct":0,"explanation":"\"Too\" before an adjective is za: za droga.","optionNotes":[null,"Za dużo means \"too much\"; before an adjective use only za.","Też means \"also\".","Drogo is an adverb; kurtka needs the adjective droga."]},{"id":"a2-functions-describing-q4","type":"multiple-choice","kind":"function","prompt":"She's a very nice person.","options":["To bardzo miło osoba.","To jest bardzo miły osoba.","To bardzo miła osoba.","To bardzo miłe osoba."],"correct":2,"explanation":"To + noun phrase in the nominative; the adjective agrees with osoba (feminine): miła.","optionNotes":["Miło is an adverb; osoba needs an adjective.","Osoba is feminine: miła, not miły.",null,"Miłe is neuter or plural; osoba is feminine."]}]};
Q["a2-functions-directions"] = {"version":1,"id":"a2-functions-directions","topic":"a2-functions-directions","level":"A2","title":"Stop: directions","passScore":3,"items":[{"id":"a2-functions-directions-q1","type":"multiple-choice","kind":"function","prompt":"Excuse me, how do I get to the station? (on foot)","options":["Przepraszam, jak idę do dworca?","Przepraszam, gdzie dojść do dworca?","Przepraszam, jak dojść do dworca?","Przepraszam, jak dojść do dworzec?"],"correct":2,"explanation":"The ready question is Jak dojść do + genitive: do dworca.","optionNotes":["A word-for-word copy of \"how do I go\"; Polish uses jak dojść.","Gdzie means \"where\"; the question needs jak (how).",null,"Do takes the genitive: dworca."]},{"id":"a2-functions-directions-q2","type":"multiple-choice","kind":"function","prompt":"Tell a stranger: \"Turn right at the traffic lights.\"","options":["Na światłach proszę skręcić w prawo.","Na światłach proszę skręca w prawo.","W światłach proszę skręcić w prawo.","Na światłach proszę skręcić do prawa."],"correct":0,"explanation":"Proszę + infinitive is the polite instruction; \"at the lights\" is na światłach, \"right\" is w prawo.","optionNotes":[null,"After proszę use the infinitive, skręcić.","Lights take na: na światłach.","Directions are w prawo / w lewo."]},{"id":"a2-functions-directions-q3","type":"multiple-choice","kind":"form","prompt":"Poczta jest naprzeciwko ___. (the bank)","options":["bank","banku","bankiem","bankowi"],"correct":1,"explanation":"Naprzeciwko (opposite) takes the genitive: banku.","optionNotes":["Nominative.",null,"Instrumental, used after przed, za, nad, pod.","Dative."]},{"id":"a2-functions-directions-q4","type":"multiple-choice","kind":"form","prompt":"The car park is behind the church.","options":["Parking jest za kościół.","Parking jest za kościoła.","Parking jest obok kościołem.","Parking jest za kościołem."],"correct":3,"explanation":"Za meaning \"behind\" (where) takes the instrumental: za kościołem.","optionNotes":["Za + accusative is for \"where to\".","Za does not take the genitive.","Obok means \"next to\" and takes the genitive.",null]}]};
Q["a2-functions-weekend-vacation"] = {"version":1,"id":"a2-functions-weekend-vacation","topic":"a2-functions-weekend-vacation","level":"A2","title":"Stop: your weekend","passScore":3,"items":[{"id":"a2-functions-weekend-vacation-q1","type":"multiple-choice","kind":"function","prompt":"Monday at work. How do you ask a colleague about the weekend?","options":["Jak minął weekend?","Jak minąłeś weekend?","Jak minął czas weekend?","Gdzie minął weekend?"],"correct":0,"explanation":"The usual question is Jak minął weekend? (\"How did the weekend pass?\").","optionNotes":[null,"The weekend is the subject: minął, not minąłeś.","Czas does not belong here.","Gdzie asks \"where\"."]},{"id":"a2-functions-weekend-vacation-q2","type":"multiple-choice","kind":"function","prompt":"You want to say that you had a good time.","options":["Był dobry czas.","Miałem super.","Było super!","Miałem dobry czas."],"correct":2,"explanation":"Polish says Było super! or Dobrze się bawiłem.","optionNotes":["A word-for-word copy; Polish uses było.","Mieć cannot go with super.",null,"A word-for-word copy of \"I had a good time\"."]},{"id":"a2-functions-weekend-vacation-q3","type":"multiple-choice","kind":"function","prompt":"We went to the mountains.","options":["Pojechaliśmy w górach.","Pojechaliśmy w góry.","Pojechaliśmy do gór.","Pojechaliśmy na góry."],"correct":1,"explanation":"The mountains take w: w góry (where to), w górach (where). Do gór is heard, but w góry is the standard phrase.","optionNotes":["W górach is \"in the mountains\" (where), not \"to\".",null,"The mountains take w, not do.","Na góry means \"onto the mountains\"."]},{"id":"a2-functions-weekend-vacation-q4","type":"multiple-choice","kind":"function","prompt":"Marta says that she was at the seaside.","options":["Byłam w morzu.","Byłam nad morze.","Byłem nad morzem.","Byłam nad morzem."],"correct":3,"explanation":"At the seaside is nad morzem; a woman says byłam.","optionNotes":["W morzu means \"in the sea\", in the water.","Nad morze is \"to the seaside\" (where to).","Byłem is a man's form.",null]}]};
Q["a2-grammar-adverbs-frequency"] = {"version":1,"id":"a2-grammar-adverbs-frequency","topic":"a2-grammar-adverbs-frequency","level":"A2","title":"Stop: adverbs and negation","passScore":3,"items":[{"id":"a2-grammar-adverbs-frequency-q1","type":"multiple-choice","kind":"form","prompt":"Nobody came.","options":["Nikt przyszedł.","Nikt nie przyszedł.","Ktoś nie przyszedł.","Nie nikt przyszedł."],"correct":1,"explanation":"Nikt needs nie before the verb: Nikt nie przyszedł.","optionNotes":["A copy of the English single negation; Polish needs nie too.",null,"Ktoś means \"somebody\".","Nie goes before the verb, not before nikt."]},{"id":"a2-grammar-adverbs-frequency-q2","type":"multiple-choice","kind":"form","prompt":"Ola gotuje bardzo ___.","options":["dobra","dobry","dobrze","dobre"],"correct":2,"explanation":"How someone does something: the adverb dobrze (well).","optionNotes":["An adjective (good); a verb needs the adverb.","An adjective (good); a verb needs the adverb.",null,"An adjective (good); a verb needs the adverb."]},{"id":"a2-grammar-adverbs-frequency-q3","type":"multiple-choice","kind":"form","prompt":"I never drink coffee.","options":["Nigdy piję kawę.","Nigdy nie piję kawy.","Nigdy nie piję kawę.","Zawsze nie piję kawy."],"correct":1,"explanation":"Nigdy needs nie, and after nie the object is in the genitive: kawy.","optionNotes":["Nigdy needs nie before the verb.",null,"After nie the object takes the genitive: kawy.","A copy of \"always don't\"; \"never\" is nigdy nie."]},{"id":"a2-grammar-adverbs-frequency-q4","type":"multiple-choice","kind":"form","prompt":"Nie lubię ryb. — Ja ___. (Me neither.)","options":["też","też nie","tak","nie też"],"correct":1,"explanation":"Agreeing with a negative: Ja też nie.","optionNotes":["Ja też means \"me too\", agreeing with a positive.",null,"Tak means \"yes\".","The order is też nie."]}]};
Q["a2-grammar-comparison"] = {"version":1,"id":"a2-grammar-comparison","topic":"a2-grammar-comparison","level":"A2","title":"Stop: comparing","passScore":3,"items":[{"id":"a2-grammar-comparison-q1","type":"multiple-choice","kind":"form","prompt":"Ten hotel jest ___ niż tamten. (cheaper)","options":["bardziej tani","tańszy","taniej","najtańszy"],"correct":1,"explanation":"Short adjectives take -szy: tani → tańszy.","optionNotes":["Bardziej is for long adjectives; tani has its own form.",null,"Taniej is the adverb (it's cheaper to…).","Najtańszy means \"the cheapest\"."]},{"id":"a2-grammar-comparison-q2","type":"multiple-choice","kind":"form","prompt":"To ___ pizza w mieście! (the best)","options":["najlepsza","najbardziej dobra","lepsza","najlepiej"],"correct":0,"explanation":"Dobry is irregular: lepszy, najlepszy; feminine najlepsza.","optionNotes":[null,"A word-for-word copy of \"most good\"; dobry has its own form.","Lepsza means \"better\".","Najlepiej is the adverb (best, as in \"cooks best\")."]},{"id":"a2-grammar-comparison-q3","type":"multiple-choice","kind":"form","prompt":"Ola mówi po polsku ___ niż ja. (better)","options":["lepsza","lepszy","lepiej","dobrzej"],"correct":2,"explanation":"Comparing actions needs the adverb: dobrze → lepiej.","optionNotes":["An adjective; mówić needs an adverb.","An adjective; mówić needs an adverb.",null,"Not a word: dobrze is irregular."]},{"id":"a2-grammar-comparison-q4","type":"multiple-choice","kind":"form","prompt":"Mój brat jest starszy niż ___.","options":["mnie","ja","mi","mną"],"correct":1,"explanation":"After niż the nominative: niż ja. (With od: ode mnie.)","optionNotes":["In careful Polish niż takes the nominative (niż ja); mnie goes with od: ode mnie.",null,"Dative.","Instrumental."]}]};
Q["a2-grammar-conjunctions-basic"] = {"version":1,"id":"a2-grammar-conjunctions-basic","topic":"a2-grammar-conjunctions-basic","level":"A2","title":"Stop: conjunctions","passScore":3,"items":[{"id":"a2-grammar-conjunctions-basic-q1","type":"multiple-choice","kind":"form","prompt":"Ja jestem z Polski, ___ Tom z Anglii.","options":["i","a","czy","więc"],"correct":1,"explanation":"A contrast between two people takes a.","optionNotes":["I adds something similar; for a contrast use a.",null,"Czy means \"or\" in questions.","Więc means \"so\"."]},{"id":"a2-grammar-conjunctions-basic-q2","type":"multiple-choice","kind":"form","prompt":"Myślę, ___ masz rację.","options":["że","bo","czy","a"],"correct":0,"explanation":"\"That\" after verbs of thinking is że, and it cannot be dropped.","optionNotes":[null,"Bo means \"because\".","Czy means \"whether\" or \"or\".","A means \"and, while\"."]},{"id":"a2-grammar-conjunctions-basic-q3","type":"multiple-choice","kind":"form","prompt":"Chcesz kawę ___ herbatę? (asking which one)","options":["albo","czy","a","i"],"correct":1,"explanation":"\"Or\" in a question about a choice is czy.","optionNotes":["Albo is \"or\" in statements: Wezmę kawę albo herbatę.",null,"A means \"and, while\".","I means \"and\"."]},{"id":"a2-grammar-conjunctions-basic-q4","type":"multiple-choice","kind":"form","prompt":"Nie poszłam do pracy, ___ byłam chora.","options":["więc","bo","że","ale"],"correct":1,"explanation":"The reason comes after bo (because).","optionNotes":["Więc (so) introduces a result, not a reason.",null,"Że means \"that\".","Ale means \"but\"."]}]};
Q["a2-grammar-numbers-with-nouns"] = {"version":1,"id":"a2-grammar-numbers-with-nouns","topic":"a2-grammar-numbers-with-nouns","level":"A2","title":"Stop: numbers with nouns","passScore":3,"items":[{"id":"a2-grammar-numbers-with-nouns-q1","type":"multiple-choice","kind":"form","prompt":"Mam pięć ___. (cats)","options":["kotów","koty","kot","kota"],"correct":0,"explanation":"From 5 on, the genitive plural: pięć kotów.","optionNotes":[null,"Koty is the form after 2, 3, 4.","Kot is the form after 1.","Kota is the singular accusative."]},{"id":"a2-grammar-numbers-with-nouns-q2","type":"multiple-choice","kind":"form","prompt":"Poproszę ___ kawy.","options":["dwa","dwie","dwoje","dwóch"],"correct":1,"explanation":"Kawa is feminine, so 2 is dwie.","optionNotes":["Dwa is for masculine (not men) and neuter nouns.",null,"Dwoje is for children (B1).","Dwóch is for men (B1)."]},{"id":"a2-grammar-numbers-with-nouns-q3","type":"multiple-choice","kind":"form","prompt":"Mój brat ma dwadzieścia dwa ___.","options":["lat","roki","lata","rok"],"correct":2,"explanation":"22 ends in 2, so the 2–4 form: dwadzieścia dwa lata.","optionNotes":["Lat is the 5+ form.","Not a word: the plural of rok is lata.",null,"Rok is the form after 1."]},{"id":"a2-grammar-numbers-with-nouns-q4","type":"multiple-choice","kind":"form","prompt":"Dwa autobusy ___ do centrum.","options":["jedzie","jadą","jedziemy","jechało"],"correct":1,"explanation":"After 2–4 the verb is plural: jadą.","optionNotes":["The singular verb is for 5+ (pięć autobusów jedzie).",null,"Jedziemy means \"we go\".","Jechało is the 5+ form in the past."]}]};
Q["a2-grammar-pronouns-in-cases"] = {"version":1,"id":"a2-grammar-pronouns-in-cases","topic":"a2-grammar-pronouns-in-cases","level":"A2","title":"Stop: pronouns in cases","passScore":3,"items":[{"id":"a2-grammar-pronouns-in-cases-q1","type":"multiple-choice","kind":"form","prompt":"Lubisz Kasię? — Tak, lubię ___.","options":["ją","jej","nią","ona"],"correct":0,"explanation":"Lubić takes the accusative; \"her\" is ją.","optionNotes":[null,"Jej is the genitive or dative, used after nie: Nie lubię jej.","Nią is the instrumental after a preposition: z nią.","Ona is the subject form."]},{"id":"a2-grammar-pronouns-in-cases-q2","type":"multiple-choice","kind":"form","prompt":"To prezent dla ___. (him)","options":["go","jego","niego","nim"],"correct":2,"explanation":"After a preposition he / him takes the n- form; dla + genitive: dla niego.","optionNotes":["Go is never used after a preposition.","Jego is the long form without a preposition (and also means \"his\").",null,"Nim is the instrumental or locative: z nim, o nim."]},{"id":"a2-grammar-pronouns-in-cases-q3","type":"multiple-choice","kind":"form","prompt":"Idziesz z ___ do kina? (us)","options":["nas","nami","nam","my"],"correct":1,"explanation":"Z meaning \"with\" takes the instrumental: z nami.","optionNotes":["Nas is the genitive, accusative or locative.",null,"Nam is the dative.","My is the subject form."]},{"id":"a2-grammar-pronouns-in-cases-q4","type":"multiple-choice","kind":"form","prompt":"Ania ma urodziny. Kupiłem ___ kwiaty.","options":["ją","nią","jej","niej"],"correct":2,"explanation":"The person who gets something is in the dative: jej (to her).","optionNotes":["Ją is the accusative (the object); the flowers are the object here.","Nią is the instrumental after a preposition.",null,"Niej is used only after a preposition."]}]};
Q["a2-verbs-aspect-introduction"] = {"version":1,"id":"a2-verbs-aspect-introduction","topic":"a2-verbs-aspect-introduction","level":"A2","title":"Stop: aspect","passScore":3,"items":[{"id":"a2-verbs-aspect-introduction-q1","type":"multiple-choice","kind":"form","prompt":"Kiedyś codziennie ___ kawę. (I used to drink coffee every day.)","options":["będę wypić","piłam","wypiłam","wypiję"],"correct":1,"explanation":"A habit (codziennie) takes the imperfective: piłam.","optionNotes":["Będę never goes with a perfective infinitive.",null,"The perfective is for one finished drink, not a habit.","Wypiję is the future: \"I'll drink it up\"."]},{"id":"a2-verbs-aspect-introduction-q2","type":"multiple-choice","kind":"form","prompt":"Wczoraj ___ nowy telefon. (I bought a new phone.)","options":["kupowałem","kupiłem","kupię","kupuję"],"correct":1,"explanation":"One finished purchase takes the perfective: kupiłem.","optionNotes":["Kupowałem means \"I was buying\" or \"I used to buy\".",null,"Kupię is the future: \"I'll buy\".","Kupuję is the present."]},{"id":"a2-verbs-aspect-introduction-q3","type":"multiple-choice","kind":"form","prompt":"What is the perfective partner of brać (take)?","options":["wybrać","brać się","wziąć","zbrać"],"correct":2,"explanation":"Brać / wziąć is a pair of two different verbs.","optionNotes":["Wybrać is a different verb: \"choose\".","Brać się is a different verb with się.",null,"Not a word: you cannot guess the prefix."]},{"id":"a2-verbs-aspect-introduction-q4","type":"multiple-choice","kind":"form","prompt":"Wczoraj cały wieczór ___ telewizję.","options":["obejrzeliśmy","obejrzymy","oglądamy","oglądaliśmy"],"correct":3,"explanation":"Cały wieczór (all evening) is about how long: imperfective, oglądaliśmy.","optionNotes":["The perfective shows a finished result, not how long.","Obejrzymy is the future.","Wczoraj needs the past.",null]}]};
Q["a2-verbs-future-tense"] = {"version":1,"id":"a2-verbs-future-tense","topic":"a2-verbs-future-tense","level":"A2","title":"Stop: future tense","passScore":3,"items":[{"id":"a2-verbs-future-tense-q1","type":"multiple-choice","kind":"form","prompt":"Jutro ___ zakupy. (I'll get the shopping done tomorrow.)","options":["będę zrobię","robiłem","zrobię","będę zrobić"],"correct":2,"explanation":"One finished action in the future: the perfective form zrobię, no będę.","optionNotes":["The perfective future needs no będę.","Robiłem is the past.",null,"Będę goes only with an imperfective infinitive."]},{"id":"a2-verbs-future-tense-q2","type":"multiple-choice","kind":"form","prompt":"Jutro cały dzień ___ pracować.","options":["byłem","będę","zrobię","jestem"],"correct":1,"explanation":"Imperfective future: będę + infinitive.","optionNotes":["Byłem is the past and cannot go with an infinitive.",null,"Zrobię is a verb of its own; it cannot help another verb.","Jestem + infinitive is not a future."]},{"id":"a2-verbs-future-tense-q3","type":"multiple-choice","kind":"form","prompt":"Which sentence is correct?","options":["Będę kupię bilet.","Kupię bilet.","Będę kupić bilet.","Będę kupuję bilet."],"correct":1,"explanation":"Kupić is perfective: its present-looking form kupię already means \"I'll buy\".","optionNotes":["Two futures in one: drop będę.",null,"Będę does not go with a perfective infinitive.","Będę is followed by an infinitive, not a present form."]},{"id":"a2-verbs-future-tense-q4","type":"multiple-choice","kind":"form","prompt":"Wieczorem ___ do kina. (I'll go to the cinema in the evening.)","options":["pojdę","pójdzię","poszedłem","pójdę"],"correct":3,"explanation":"The future of pójść keeps ó: pójdę.","optionNotes":["Spelling: pójdę is written with ó.","Not a word: the ending is -ę without i.","Poszedłem is the past.",null]}]};
Q["a2-verbs-modals-necessity"] = {"version":1,"id":"a2-verbs-modals-necessity","topic":"a2-verbs-modals-necessity","level":"A2","title":"Stop: must, should, can","passScore":3,"items":[{"id":"a2-verbs-modals-necessity-q1","type":"multiple-choice","kind":"form","prompt":"You mustn't smoke here.","options":["Tu nie musisz palić.","Tu nie wolno palić.","Tu nie trzeba palić.","Tu nie warto palić."],"correct":1,"explanation":"A ban is nie wolno. Nie musisz means \"you don't have to\".","optionNotes":["Nie musisz means \"you don't have to\", not \"you mustn't\".",null,"Nie trzeba means \"there's no need\".","Nie warto means \"it's not worth it\"."]},{"id":"a2-verbs-modals-necessity-q2","type":"multiple-choice","kind":"form","prompt":"You should rest. (to a woman, a friend)","options":["Powinien odpocząć.","Powinnaś odpocząć.","Powinieneś odpocząć.","Powinna odpocząć."],"correct":1,"explanation":"Powinien agrees with the person: \"you\" to a woman is powinnaś.","optionNotes":["Powinien means \"he should\".",null,"Powinieneś is \"you should\" to a man.","Powinna alone means \"she should\"."]},{"id":"a2-verbs-modals-necessity-q3","type":"multiple-choice","kind":"form","prompt":"___ zobaczyć to muzeum, jest bardzo ciekawe. (It's worth)","options":["Warto","Wolno","Nie trzeba","Nie wolno"],"correct":0,"explanation":"\"It's worth (doing)\" is warto + infinitive.","optionNotes":[null,"Wolno means \"one may\" (it's allowed).","Nie trzeba means \"there's no need\".","Nie wolno means \"you mustn't\"."]},{"id":"a2-verbs-modals-necessity-q4","type":"multiple-choice","kind":"form","prompt":"Jutro ___ iść do lekarza. (I have to)","options":["trzeba","muszę","powinien","wolno"],"correct":1,"explanation":"With a person (I) use musieć: muszę. Trzeba has no person.","optionNotes":["Trzeba has no person: it means \"one has to\".",null,"Powinien is \"he should\".","Wolno means \"one may\"."]}]};
Q["a2-verbs-motion-verbs-basics"] = {"version":1,"id":"a2-verbs-motion-verbs-basics","topic":"a2-verbs-motion-verbs-basics","level":"A2","title":"Stop: verbs of motion","passScore":3,"items":[{"id":"a2-verbs-motion-verbs-basics-q1","type":"multiple-choice","kind":"form","prompt":"Codziennie ___ do pracy pieszo.","options":["idę","chodzę","jadę","jeżdżę"],"correct":1,"explanation":"A habit on foot: chodzić. Codziennie is the signal word.","optionNotes":["Idę is for one trip now or planned.",null,"Jadę is by vehicle, one trip.","Jeżdżę is by vehicle; pieszo means on foot."]},{"id":"a2-verbs-motion-verbs-basics-q2","type":"multiple-choice","kind":"form","prompt":"Teraz ___ do sklepu, zaraz wracam. (on foot)","options":["chodzę","jeżdżę","latam","idę"],"correct":3,"explanation":"One trip in one direction, right now: iść.","optionNotes":["Chodzę is for habits, not for one trip now.","Jeżdżę is by vehicle and for habits.","Latam is for flying, as a habit.",null]},{"id":"a2-verbs-motion-verbs-basics-q3","type":"multiple-choice","kind":"form","prompt":"W soboty ___ do babci samochodem.","options":["jeżdżę","jadę","idę","lecę"],"correct":0,"explanation":"A repeated trip by car: jeździć. W soboty (on Saturdays) shows a habit.","optionNotes":[null,"Jadę is for one trip, not for every Saturday.","Idę is on foot.","Lecę is for flying."]},{"id":"a2-verbs-motion-verbs-basics-q4","type":"multiple-choice","kind":"form","prompt":"W zeszłym roku ___ do Hiszpanii. (we, by plane)","options":["poszliśmy","polecieliśmy","latamy","polecimy"],"correct":1,"explanation":"One finished trip by plane in the past: the perfective polecieć.","optionNotes":["Pójść is on foot.",null,"Latamy is present and means a habit.","Polecimy is the future."]}]};
Q["a2-verbs-past-tense"] = {"version":1,"id":"a2-verbs-past-tense","topic":"a2-verbs-past-tense","level":"A2","title":"Stop: past tense","passScore":3,"items":[{"id":"a2-verbs-past-tense-q1","type":"multiple-choice","kind":"form","prompt":"Tomek i Ola ___ w kinie.","options":["były","byli","był","byliśmy"],"correct":1,"explanation":"A group with at least one man takes -li: byli.","optionNotes":["-ły is for groups without men; Tomek is a man.",null,"Był is singular: \"he was\".","Byliśmy means \"we were\"."]},{"id":"a2-verbs-past-tense-q2","type":"multiple-choice","kind":"form","prompt":"(a man speaking) Wczoraj ___ do pracy pieszo.","options":["szłem","szedłem","szedł","szłam"],"correct":1,"explanation":"The past of iść for a man is szedłem; the e drops only in szłam, szła, szli.","optionNotes":["Not a word: a man says szedłem.",null,"Szedł is \"he went\", not \"I went\".","Szłam is a woman's form."]},{"id":"a2-verbs-past-tense-q3","type":"multiple-choice","kind":"form","prompt":"Ania i Kasia nie ___ czasu.","options":["miały","mieli","miali","miała"],"correct":0,"explanation":"Two women: the -ły form, miały.","optionNotes":[null,"Mieli is for a group with a man.","Not a word: before -li the e comes back (mieli).","Miała is singular: \"she had\"."]},{"id":"a2-verbs-past-tense-q4","type":"multiple-choice","kind":"form","prompt":"(a woman speaking) Było gorąco i nie ___ spać.","options":["mógłam","mogłam","mogła","mogłem"],"correct":1,"explanation":"Móc: ó appears only in mógł (he could). A woman says mogłam.","optionNotes":["Spelling: ó only in mógł.",null,"Mogła is \"she could\".","Mogłem is a man's form."]}]};
Q["a2-verbs-reflexive-sie"] = {"version":1,"id":"a2-verbs-reflexive-sie","topic":"a2-verbs-reflexive-sie","level":"A2","title":"Stop: verbs with się","passScore":3,"items":[{"id":"a2-verbs-reflexive-sie-q1","type":"multiple-choice","kind":"form","prompt":"I'm learning Polish.","options":["Uczę polski.","Uczę się polskiego.","Uczę się polski.","Się uczę polskiego."],"correct":1,"explanation":"\"Learn\" is uczyć się + genitive: polskiego.","optionNotes":["Uczyć without się means \"teach\".",null,"Uczyć się takes the genitive: polskiego.","Się never starts a sentence."]},{"id":"a2-verbs-reflexive-sie-q2","type":"multiple-choice","kind":"form","prompt":"Jak ___ nazywasz?","options":["się","sobie","cię","ty"],"correct":0,"explanation":"Nazywać się always has się, the same for every person.","optionNotes":[null,"Sobie is the dative \"to yourself\".","Cię is \"you\" as an object; the verb needs się.","Ty is the subject \"you\", not part of the verb."]},{"id":"a2-verbs-reflexive-sie-q3","type":"multiple-choice","kind":"form","prompt":"Wczoraj ___ w kawiarni. (we met)","options":["spotkaliśmy","spotkaliśmy się","spotykaliśmy się","spotkaliśmy nas"],"correct":1,"explanation":"Meeting each other is spotkać się; one meeting in the past takes the perfective.","optionNotes":["Without się it means \"we ran into (someone)\" and needs an object.",null,"The imperfective means \"we used to meet\" or \"we were meeting\".","\"Each other\" is się, not nas."]},{"id":"a2-verbs-reflexive-sie-q4","type":"multiple-choice","kind":"form","prompt":"Mój syn boi się ___. (dogs)","options":["psy","psów","psami","psach"],"correct":1,"explanation":"Bać się takes the genitive: psów.","optionNotes":["Nominative or accusative; bać się takes the genitive.",null,"Instrumental.","Locative."]}]};
Q["a2-vocabulary-shopping-clothes"] = {"version":1,"id":"a2-vocabulary-shopping-clothes","topic":"a2-vocabulary-shopping-clothes","level":"A2","title":"Stop: shopping and clothes","passScore":3,"items":[{"id":"a2-vocabulary-shopping-clothes-q1","type":"multiple-choice","kind":"meaning","prompt":"Can I try on this jacket?","options":["Czy mogę próbować tę kurtkę?","Czy mogę przymierzyć tę kurtkę?","Czy mogę nosić tę kurtkę?","Czy mogę przymierzyć ta kurtka?"],"correct":1,"explanation":"\"Try on\" clothes is przymierzyć, + accusative: tę kurtkę.","optionNotes":["Próbować means \"try, taste\", not \"try on\".",null,"Nosić means \"wear\".","The object needs the accusative: tę kurtkę."]},{"id":"a2-vocabulary-shopping-clothes-q2","type":"multiple-choice","kind":"form","prompt":"Te spodnie ___ za długie.","options":["są","jest","ma","będzie"],"correct":0,"explanation":"Spodnie is plural only, so the verb is plural: są.","optionNotes":[null,"Jest is singular; spodnie is a plural word.","Mieć does not describe here; use być.","Będzie is singular (and future)."]},{"id":"a2-vocabulary-shopping-clothes-q3","type":"multiple-choice","kind":"function","prompt":"What size do you wear? (formal, to a woman)","options":["Jaki rozmiar pani jest?","Jaki rozmiar pan nosi?","Jaki rozmiar pani nosi?","Jaka jest pani rozmiar?"],"correct":2,"explanation":"Polish says \"which size do you wear\": Jaki rozmiar pani nosi?","optionNotes":["A copy of \"what size are you\"; Polish uses nosić.","Pan is for a man.",null,"Rozmiar is masculine, so jaki (Jaki jest pani rozmiar? is fine); jaka is feminine."]},{"id":"a2-vocabulary-shopping-clothes-q4","type":"multiple-choice","kind":"form","prompt":"Mam nową ___ kurtkę. (black)","options":["czarny","czarna","czarne","czarną"],"correct":3,"explanation":"Colours are adjectives and agree with the noun: kurtkę (accusative feminine) → czarną.","optionNotes":["Masculine.","Feminine nominative; the object needs the accusative.","Neuter or plural.",null]}]};
Q["a2-vocabulary-travel-transport"] = {"version":1,"id":"a2-vocabulary-travel-transport","topic":"a2-vocabulary-travel-transport","level":"A2","title":"Stop: travel","passScore":3,"items":[{"id":"a2-vocabulary-travel-transport-q1","type":"multiple-choice","kind":"meaning","prompt":"I'm getting off at the next stop.","options":["Wychodzę z następnego przystanku.","Wysiadam na następnym przystanku.","Wsiadam na następnym przystanku.","Wysiadam do następnego przystanku."],"correct":1,"explanation":"Getting off a vehicle is wysiadać.","optionNotes":["You leave a vehicle, not a stop: wysiadać z autobusu.",null,"Wsiadać is \"get on\".","Do means \"to\"; a stop is where you are: na przystanku."]},{"id":"a2-vocabulary-travel-transport-q2","type":"multiple-choice","kind":"meaning","prompt":"Pociąg do Krakowa odjeżdża z ___ drugiego.","options":["peronu","lotniska","recepcji","rozkładu"],"correct":0,"explanation":"A train leaves from a platform: z peronu.","optionNotes":[null,"Lotnisko is an airport.","Recepcja is a hotel reception.","Rozkład jazdy is a timetable."]},{"id":"a2-vocabulary-travel-transport-q3","type":"multiple-choice","kind":"form","prompt":"Jadę ___ do Lublina. (I'm going to Lublin by train.)","options":["na pociągu","z pociągiem","pociąg","pociągiem"],"correct":3,"explanation":"\"By train\" is the instrumental with no preposition: pociągiem.","optionNotes":["No preposition for \"by\".","Z pociągiem means \"together with a train\".","The nominative cannot say \"by\".",null]},{"id":"a2-vocabulary-travel-transport-q4","type":"multiple-choice","kind":"meaning","prompt":"Chcemy zarezerwować ___. (a double room)","options":["pokój jednoosobowy","bilet dwuosobowy","pokój dwuosobowy","pokój powrotny"],"correct":2,"explanation":"A double room is pokój dwuosobowy.","optionNotes":["Jednoosobowy is a single room.","Bilet is a ticket, not a room.",null,"Powrotny is for a return ticket."]}]};
